using System;
int[] a = { 1, 2, 2, 4 };
int Bound(bool upper) { int low = 0, high = a.Length;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (a[mid] < 2 || (upper && a[mid] == 2)) low = mid + 1;
        else high = mid;
    } return low;
}
Console.WriteLine($"{Bound(false)},{Bound(true)}");

