for (int i = 1; i < a.Length; i++) {
    int saved = a[i], j = i;
    while (j > 0 && a[j - 1] > saved) { a[j] = a[j - 1]; j--; shifts++; }
    a[j] = saved;
}
Console.WriteLine(string.Join(",", a));
Console.WriteLine(string.Join(",", arrival));
Console.WriteLine(shifts);

