using System;
int[] invoice = { 8, -3, 4, 4 }; long target = 5; int witnesses = 0;
for (int mask = 0; mask < (1 << invoice.Length); mask++) {
    long sum = 0;
    for (int i = 0; i < invoice.Length; i++)
        if ((mask & (1 << i)) != 0) sum += invoice[i];
    if (sum == target) { Console.WriteLine(mask); witnesses++; }
}
