for (int i = 1, j = 0; i < pattern.Length; i++) {
    while (j > 0 && pattern[i] != pattern[j]) j = prefix[j - 1];
    if (pattern[i] == pattern[j]) j++;
    prefix[i] = j;
}
Console.WriteLine(string.Join(",", prefix));
